-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Finanzierungsarten > Miete
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Bleibt der Vermieter bei der Miete von IT-Hardware der Eigentümer der Ausrüstung?', 2, '[{"text": "Ja", "correct": true, "because": "Bei Miete bleibt das Eigentum beim Vermieter"}, {"text": "Nein", "correct": false, "because": "Eigentum wird nicht übertragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind bei der Miete von Servern für einen IT-Betrieb regelmäßige Zahlungen erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Miete bedeutet regelmäßige Mietzahlungen"}, {"text": "Nein", "correct": false, "because": "Zahlungen sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch die Miete von Software hohe Anfangsinvestitionen vermeiden?', 2, '[{"text": "Ja", "correct": true, "because": "Miete verteilt Kosten über die Laufzeit"}, {"text": "Nein", "correct": false, "because": "Miete reduziert Anfangskosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist bei der Miete von IT-Ausrüstung eine Abschreibung durch den Betrieb möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Das Eigentum liegt beim Vermieter"}, {"text": "Ja", "correct": false, "because": "Abschreibung nur beim Eigentümer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb bei der Miete von Hardware die Ausrüstung nach Vertragsende behalten?', 2, '[{"text": "Nein", "correct": true, "because": "Miete beinhaltet keine Eigentumsübertragung"}, {"text": "Ja", "correct": false, "because": "Keine Kaufoption wie beim Leasing"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein wesentliches Merkmal der Finanzierungsart Miete für einen IT-Betrieb?', 2, '[{"text": "Nutzung ohne Eigentum", "correct": true, "because": "Miete bedeutet Nutzung, nicht Besitz"}, {"text": "Sofortige Eigentumsübertragung", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Einmalige Zahlung", "correct": false, "because": "Miete erfordert regelmäßige Zahlungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen einem IT-Betrieb typischerweise bei der Miete von Servern?', 3, '[{"text": "Monatliche Mietzahlungen", "correct": true, "because": "Miete bedeutet regelmäßige Zahlungen"}, {"text": "Einmalige Anschaffungskosten", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Nur Wartungskosten", "correct": false, "because": "Mietzahlungen sind primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb durch die Miete von Software?', 3, '[{"text": "Geringere Anfangskosten", "correct": true, "because": "Miete verteilt Kosten über die Zeit"}, {"text": "Langfristige Kostenersparnis", "correct": false, "because": "Kauf kann langfristig günstiger sein"}, {"text": "Eigentum an der Software", "correct": false, "because": "Eigentum bleibt beim Vermieter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Finanzierungsquelle wird bei der Miete von IT-Ausrüstung häufig genutzt?', 2, '[{"text": "Betriebsmittel", "correct": true, "because": "Mietzahlungen kommen aus laufenden Mitteln"}, {"text": "Eigenkapital", "correct": false, "because": "Weniger üblich für laufende Zahlungen"}, {"text": "Fremdkapital", "correct": false, "because": "Leasing ist eher Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Miete von Hardware für einen IT-Betrieb?', 3, '[{"text": "Keine Eigentumsübertragung", "correct": true, "because": "Eigentum bleibt beim Vermieter"}, {"text": "Hohe Anfangsinvestition", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Technologische Veralterung", "correct": false, "because": "Miete kann Flexibilität bieten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Finanzierungsart Miete für einen IT-Betrieb?', 4, '[{"text": "Nutzung ohne Eigentum", "correct": true, "because": "Eigentum bleibt beim Vermieter"}, {"text": "Regelmäßige Mietzahlungen", "correct": true, "because": "Miete erfordert laufende Kosten"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Miete reduziert Anfangskosten"}, {"text": "Flexibilität bei Vertragslaufzeit", "correct": true, "because": "Mietverträge können flexibel sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Miete von IT-Ausrüstung für einen IT-Betrieb?', 3, '[{"text": "Geringere Anfangskosten", "correct": true, "because": "Kosten werden verteilt"}, {"text": "Flexibilität bei Austausch", "correct": true, "because": "Miete erlaubt Rückgabe"}, {"text": "Eigentumsübertragung", "correct": false, "because": "Eigentum bleibt beim Vermieter"}, {"text": "Liquiditätsschonung", "correct": true, "because": "Kein Kapital gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Miete von Hardware für einen IT-Betrieb?', 4, '[{"text": "Keine Eigentumsübertragung", "correct": true, "because": "Eigentum bleibt beim Vermieter"}, {"text": "Laufende Kosten", "correct": true, "because": "Regelmäßige Zahlungen erforderlich"}, {"text": "Hohe Anfangsinvestition", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Langfristig höhere Gesamtkosten", "correct": true, "because": "Miete kann teurer als Kauf sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen bei der Miete von Software für einen IT-Betrieb?', 3, '[{"text": "Monatliche Mietzahlungen", "correct": true, "because": "Miete bedeutet regelmäßige Kosten"}, {"text": "Wartungskosten", "correct": true, "because": "Wartung kann zusätzlich anfallen"}, {"text": "Einmalige Anschaffungskosten", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Verwaltungsgebühren", "correct": true, "because": "Kann bei Mietverträgen anfallen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Miete von anderen Finanzierungsarten wie Kauf für einen IT-Betrieb?', 3, '[{"text": "Keine Eigentumsübertragung", "correct": true, "because": "Eigentum bleibt beim Vermieter"}, {"text": "Regelmäßige Zahlungen", "correct": true, "because": "Miete erfordert laufende Kosten"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Das gilt für Kauf"}, {"text": "Flexibilität bei Rückgabe", "correct": true, "because": "Miete erlaubt Rückgabe"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Bei der Miete von Hardware bleibt das Eigentum beim Vermieter. b) Miete erfordert eine hohe Anfangsinvestition.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Miete von Software reduziert Anfangskosten. b) Der Betrieb kann die Software abschreiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anfangskosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Miete von Servern erfordert regelmäßige Zahlungen. b) Der Betrieb wird Eigentümer nach Vertragsende.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zahlungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Miete schont die Liquidität eines IT-Betriebs. b) Miete ist langfristig günstiger als Kauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Liquidität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Bei der Miete von IT-Ausrüstung entstehen monatliche Kosten. b) Der Betrieb kann die Ausrüstung behalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monatliche Kosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

